input.mermaid:
graph TD
    A[Start] --> B{Inputs J and K};
    B -- J=0, K=0 --> C[Q remains the same (Hold)];
    B -- J=1, K=0 --> D[Q becomes 1 (Set)];
    B -- J=0, K=1 --> E[Q becomes 0 (Reset)];
    B -- J=1, K=1 --> F[Q toggles (Flip)];
    C --> G[End];
    D --> G;
    E --> G;
    F --> G;

flowchart TD
    A[Start: Data Set] --> B{Calculate Feature Importance / Information Gain};
    B --> C{Find Best Split Point (Test Feature)};
    C --> D{Split Data into Child Nodes};
    D --> E[Evaluate Child Nodes];
    E --> F{Is the Node Pure? (All samples belong to the same class)};
    F -- Yes --> G[Create Terminal Node / Class Prediction];
    F -- No --> H[Recurse: Repeat Steps B-F on Child Node];
    H --> E;
    G --> I[Prediction Complete];
